import {voicesFor,selectedVoice,voiceChoiceKey,voiceBodyFamily} from './voice-catalogue.js';
export function mountVoiceLibrary({document,state,identity,preview,selectVoice,download,status}){
 const el=id=>document.getElementById(id);let pending=0;const installed=new Map();
 function render(){const current=identity(),voices=voicesFor(current),pack=voices[0]?.pack,info=installed.get(pack)||{installed:false};
  el('voice-library-heading').textContent=current.name+' · '+current.gender+' · '+(current.voiceLanguage||'en').toUpperCase();el('voice-library-install').textContent=info.busy?'Downloading collection · Stop cancels safely':info.installed?'Installed · shared model ready offline':globalThis.__TAURI__?'Not installed · download this collection once':'Download collections in the Windows app';
  const downloadButton=el('voice-library-download');downloadButton.hidden=!globalThis.__TAURI__;downloadButton.textContent=info.busy?'Cancel download':info.installed?'Repair collection':'Download collection';
  el('voice-library-list').replaceChildren();const query=el('voice-library-search').value.trim().toLowerCase(),chosen=selectedVoice(current,state.data.voiceChoices),family=voiceBodyFamily(current);
  for(const voice of voices.filter(v=>[v.name,v.style,v.accent].join(' ').toLowerCase().includes(query))){const card=document.createElement('article');card.className='voice-card';card.dataset.voice=voice.id;card.classList.toggle('selected',chosen?.id===voice.id);const title=document.createElement('strong'),note=document.createElement('small'),buttons=document.createElement('div'),listen=document.createElement('button'),choose=document.createElement('button');title.textContent=voice.name;note.textContent=voice.accent+' · '+voice.style;listen.textContent='Listen';listen.disabled=info.busy||!info.installed||!globalThis.__TAURI__;listen.onclick=()=>preview(voice.id);choose.textContent=chosen?.id===voice.id?'Default ✓':'Set default';choose.setAttribute('aria-pressed',String(chosen?.id===voice.id));choose.onclick=()=>selectVoice(voice.id);buttons.append(listen,choose);card.append(title,note,buttons);el('voice-library-list').append(card);}
  el('voice-library-empty').hidden=el('voice-library-list').children.length>0;el('voice-library-scope').textContent='Saved for '+current.name+' · '+family+' body · '+(current.voiceLanguage||'en')+' · '+pack+'. Model files are shared, not downloaded per speaker.';
 }
 el('voice-library-search').oninput=render;el('voice-library-download').onclick=()=>download();el('voice-library-auto').onclick=()=>selectVoice('auto');async function refresh(){const token=++pending,pack=voicesFor(identity())[0]?.pack;render();const info=await status(pack).catch(()=>({installed:false}));if(token!==pending)return;installed.set(pack,info);render();}return {refresh:()=>void refresh()};
}
